'use strict';

// MODULES //

var floor = require( '@stdlib/math/base/special/floor' );
var numelDimension = require( '@stdlib/ndarray/base/numel-dimension' );
var getStride = require( '@stdlib/ndarray/base/stride' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );


// VARIABLES //

var M = 3;


// MAIN //

/**
* Reverses the elements of a one-dimensional single-precision floating-point ndarray.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing one input ndarray
* @returns {void}
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
* var ndarray = require( '@stdlib/ndarray/base/ctor' );
*
* var xbuf = new Float32Array( [ 1.0, 2.0, 3.0 ] );
* var x = new ndarray( 'float32', xbuf, [ 3 ], [ 1 ], 0, 'row-major' );
*
* srev( [ x ] );
* // xbuf => <Float32Array>[ 3.0, 2.0, 1.0 ]
*/
function srev( arrays ) {
	var strideX;
	var offset;
	var tmp;
	var ix;
	var iy;
	var m;
	var n;
	var i;
	var x;
	var N;
	var d;

	x = arrays[ 0 ];
	N = numelDimension( x, 0 );

	if ( N <= 0 ) {
		return;
	}
	d = getData( x );
	strideX = getStride( x, 0 );
	offset = getOffset( x );

	n = floor( N/2 );
	ix = offset;

	// Use loop unrolling if the stride is equal to `1`...
	if ( strideX === 1 ) {
		m = n % M;
		iy = ix + N - 1;

		// If we have a remainder, run a clean-up loop...
		if ( m > 0 ) {
			for ( i = 0; i < m; i++ ) {
				tmp = d[ ix ];
				d[ ix ] = d[ iy ];
				d[ iy ] = tmp;
				ix += strideX;
				iy -= strideX;
			}
		}
		if ( n < M ) {
			return;
		}
		for ( i = m; i < n; i += M ) {
			tmp = d[ ix ];
			d[ ix ] = d[ iy ];
			d[ iy ] = tmp;

			tmp = d[ ix+1 ];
			d[ ix+1 ] = d[ iy-1 ];
			d[ iy-1 ] = tmp;

			tmp = d[ ix+2 ];
			d[ ix+2 ] = d[ iy-2 ];
			d[ iy-2 ] = tmp;

			ix += M;
			iy -= M;
		}
		return;
	}
	iy = ix + ( ( N-1 ) * strideX );
	for ( i = 0; i < n; i++ ) {
		tmp = d[ ix ];
		d[ ix ] = d[ iy ];
		d[ iy ] = tmp;
		ix += strideX;
		iy -= strideX;
	}
}


// EXPORTS //

module.exports = srev;
